{"claims":[{"claim_text":"DSA pledges to support Marriott hotel workers by not eating, sleeping or meeting at any Marriott on strike or in the event of a boycott, and will encourage its members to do the same.", "claim_types":["policy_position"],"evidence_ids":[2]},{"claim_text":"DSA pledges to respect women and not engage or tolerate harassment of hotel workers in any form.", "claim_types":["policy_position"],"evidence_ids":[3]},{"claim_text":"DSA pledges to encourage local chapters of DSA, wherever and whenever possible, to continue to support workers by joining picket lines and contributing to strike funds.", "claim_types":["policy_position"],"evidence_ids":[4]},{"claim_text":"DSA encourages members not living near hotels on strike to sign a pledge as individuals to not eat, sleep, or meet at any Marriott that goes on strike or under boycott, and to ask their local DSA chapter, union, or other community group to sign the pledge as an organization.", "claim_types":["policy_position"],"evidence_ids":[5]},{"claim_text":"DSA encourages members to follow and participate in the online actions called for by the union.", "claim_types":["policy_position"],"evidence_ids":[6]},{"claim_text":"DSA encourages members to better understand the strike by taking the time to hear and share the stories of the workers.", "claim_types":["policy_position"],"evidence_ids":[7]},{"claim_text":"Marriott is the largest and wealthiest hotel company in the world, with more employees than Facebook, Microsoft, or Boeing.", "claim_types":["factual_assertion"],"evidence_ids":[1]},{"claim_text":"The company profits of Marriott have increased 279% since the recession.", "claim_types":["factual_assertion"],"evidence_ids":[1]},{"claim_text":"UNITE HERE has been in contract negotiations with Marriott for many months in several cities.", "claim_types":["factual_assertion"],"evidence_ids":[1]},{"claim_text":"The various local unions of UNITE HERE went to their respective bargaining tables with the unifying principle that “One Job Should Be Enough”.", "claim_types":["factual_assertion"],"evidence_ids":[1]},{"claim_text":"The outcome of this fight could set an important precedent in the hotel and hospitality industry for the 270,000 workers of UNITE HERE.", "claim_types":["prediction"],"evidence_ids":[1]}],"unresolved_references":[]}
